#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# The owner's checks for 0.1: what agents could not do, because it needs the owner's own
# Windows 11 PC (RTX 5070 Ti, Chrome, Brave, Zen, a real webcam and games). Run it on the
# Linux machine that holds this repo, from a terminal you can copy out of onto Windows
# (over SSH, say):
#
#   scripts/owner-checks.sh
#
# Each check ends with pass, fail or skip and a note, written as a dated line under
# "## Owner's results" in .scratch/v1/issues/25-owners-verification.md. A re-run skips the
# checks already there, unless you name them to redo (the new line is added below the old).
# For steps 3 and 5 of the nine-step pass it runs a Linux Chromium member on this machine
# (scripts/real-media/desktop.sh and `pnpm real-media`), and stops it again when done.
# The instance address is kept in .env.owner-checks (git-ignored).
#
# 2026-11-20, the owner's decision: Vivaldi and macOS are no longer checked (Vivaldi is
# best effort, and there is no Mac to test on). Their ids, vivaldi-1080p60, macos and
# macos-1 to macos-9, are no longer asked; a line already recorded for one stays in the
# results and is ignored. Brave is the second member on Windows where Vivaldi was, and Zen
# is checked at the Firefox level (zen-watch, zen-webcam, zen-screen). Every other id is
# unchanged, so answers recorded before still count.

run_wizard() {

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$ROOT"
ENV_FILE="$ROOT/.env.owner-checks"
RESULTS="$ROOT/.scratch/v1/issues/25-owners-verification.md"
HEADING="## Owner's results"
SECRET_FILE="${GRAEAE_SETUP_SECRET_FILE:-$HOME/graeae-test-setup-secret}"
LINUX_NAME="Tux"
PAGE_TITLE="owner-check-page"
DRIVER_LABEL="owner-check"
DRIVER_DIR=""
DRIVER_PID=""
DRIVER_DISPLAY=""
LINUX_SHARING=0
REDO=()
DONE_THIS_RUN=()
[[ -f "$RESULTS" ]] || { echo "No $RESULTS: run this from the graeae repo." >&2; exit 1; }

# ── Results ───────────────────────────────────────────────────────────────

recorded() { grep -qF "· \`$1\` ·" "$RESULTS"; }
redoing() { local r; for r in "${REDO[@]}"; do [[ "$r" == "$1" ]] && return 0; done; return 1; }
pending() { redoing "$1" || ! recorded "$1"; }
any_pending() { local id; for id in "$@"; do pending "$id" && return 0; done; return 1; }

# _append LINE puts LINE at the end of the "Owner's results" list, making the heading at
# the end of the file if it is missing, and keeping any section after it in place.
_append() {
  local line="$1" tmp
  if ! grep -qxF "$HEADING" "$RESULTS"; then
    [[ -z "$(tail -c 1 "$RESULTS")" ]] || printf '\n' >> "$RESULTS"
    printf '\n%s\n' "$HEADING" >> "$RESULTS"
  fi
  tmp=$(mktemp)
  awk -v head="$HEADING" -v new="$line" '
    function emit() { if (!content) print ""; print new; done = 1 }
    !done && inside && /^## / { emit(); print ""; inside = 0; blanks = 0 }
    inside {
      if ($0 ~ /^[[:space:]]*$/) { blanks++; next }
      for (; blanks > 0; blanks--) print ""
      content = 1; print; next
    }
    { print }
    !done && $0 == head { inside = 1; content = 0; blanks = 0 }
    END { if (!done) emit() }
  ' "$RESULTS" > "$tmp"
  cat "$tmp" > "$RESULTS"
  rm -f "$tmp"
}

# record ID "What was checked" ["readings to add to the note"] asks pass, fail or skip
# and a note, and writes the line. Enter alone at the first question records nothing,
# so the check stays for a later run.
record() {
  local id="$1" title="$2" extra="${3:-}" answer="" result="" note="" line
  printf '\n'
  while :; do
    printf '  %s%s?%s %s[p]ass, [f]ail, [s]kip, or Enter to leave it for later:%s ' "$BOLD" "$title" "$RESET" "$DIM" "$RESET"
    read -r answer || return 1
    case "${answer,,}" in
      p|pass) result=pass ;;
      f|fail) result=fail ;;
      s|skip) result=skip ;;
      "") warn "left for later: nothing recorded for $id"; return 0 ;;
      *) continue ;;
    esac
    break
  done
  read -e -r -p "  Note (what you saw, versions, anything odd; Enter for none): " note || true
  [[ -n "$extra" ]] && note="${note:+$note. }$extra"
  line="- $(date '+%Y-%m-%d %H:%M %z') · \`$id\` · **$result** · $title${note:+ · $note}"
  _append "$line"
  DONE_THIS_RUN+=("$id: $result")
  printf '  %s✓ recorded%s %s: %s\n' "$GREEN" "$RESET" "$id" "$result"
  sleep 1
}

# countdown SECONDS "what" counts down on one line.
countdown() {
  local left="$1"
  while (( left > 0 )); do
    printf '\r  %s%d:%02d left of %s%s ' "$DIM" $((left / 60)) $((left % 60)) "$2" "$RESET"
    sleep 1
    left=$((left - 1))
  done
  printf '\r  %s✓ %s is up%s                     \n' "$GREEN" "$2" "$RESET"
}

# ── The Linux member: a virtual display and `pnpm real-media` ─────────────

driver_up() { [[ -n "$DRIVER_PID" ]] && kill -0 "$DRIVER_PID" 2>/dev/null; }

# send "command" types one line into the driver.
send() {
  driver_up || { warn "the Linux member is not running"; return 1; }
  printf '%s\n' "$1" >&3
  note "sent to the Linux member: $1"
}

# readings "in|out" prints the driver's latest video and audio line in that direction,
# without its time and label.
readings() {
  local kind line
  for kind in video audio; do
    line=$(grep -E "^[0-9:]{8} $DRIVER_LABEL $1 $kind " "$DRIVER_DIR/log" 2>/dev/null | tail -n 1 || true)
    if [[ -n "$line" ]]; then printf '%s; ' "${line#* "$DRIVER_LABEL" }"; fi
  done
  return 0
}

# live shows the driver's lines as they come until Enter.
live() {
  say "The Linux member's readings, every 5 seconds: 'in' is what it receives, 'out' what"
  say "it sends; video as size, fps and frames; audio as level (0 is silence, above 0.01 is sound)."
  printf '\n'
  tail -n 4 -f "$DRIVER_DIR/log" &
  local tailer=$!
  pause "Press Enter when you have seen enough…"
  kill "$tailer" 2>/dev/null || true
  wait "$tailer" 2>/dev/null || true
}

start_driver() {
  local invite="$1" line number=97 display="" pulse="" command
  [[ -d node_modules/@playwright/test ]] || { warn "node_modules is missing: run nix-shell --run 'pnpm install' first"; return 1; }
  # A display nothing else uses.
  while [[ -e "/tmp/.X${number}-lock" ]] && (( number > 80 )); do number=$((number - 1)); done
  DRIVER_DISPLAY=":$number"
  say "Starting a virtual display $DRIVER_DISPLAY with sound (the first time, nix may download for a minute)…"
  line=$(scripts/real-media/desktop.sh start "$DRIVER_DISPLAY" 1920x1080 | tail -n 1) || true
  for part in $line; do
    case "$part" in
      DISPLAY=*) display="${part#DISPLAY=}" ;;
      PULSE_SERVER=*) pulse="${part#PULSE_SERVER=}" ;;
    esac
  done
  [[ -n "$display" && -n "$pulse" ]] || { warn "the virtual display did not start: $line"; return 1; }

  # A fresh browser profile, so it joins by this invite and not a room it remembers.
  rm -rf "$HOME/.cache/graeae-real-media/$DRIVER_LABEL"
  DRIVER_DIR=$(mktemp -d)
  mkfifo "$DRIVER_DIR/in"
  exec 3<>"$DRIVER_DIR/in"
  command="DISPLAY=$(printf '%q' "$display") PULSE_SERVER=$(printf '%q' "$pulse") pnpm real-media"
  command+=" --url $(printf '%q' "$invite") --name $DRIVER_LABEL --pick tab:$PAGE_TITLE --webcam fake --every 5"
  say "Starting the Linux member's Chromium…"
  if command -v setsid >/dev/null 2>&1; then
    setsid nix-shell --run "$command" <&3 >"$DRIVER_DIR/log" 2>&1 &
  else
    nix-shell --run "$command" <&3 >"$DRIVER_DIR/log" 2>&1 &
  fi
  DRIVER_PID=$!

  local waited=0
  until grep -q "in the room at" "$DRIVER_DIR/log" 2>/dev/null; do
    if ! driver_up || (( waited >= 180 )); then
      warn "the Linux member did not get into the room. The end of its log:"
      tail -n 15 "$DRIVER_DIR/log" | sed 's/^/    /'
      stop_driver
      return 1
    fi
    sleep 2
    waited=$((waited + 2))
  done
  printf '  %s✓ the Linux member is in the room%s\n' "$GREEN" "$RESET"
}

stop_driver() {
  if driver_up; then
    printf 'quit\n' >&3 2>/dev/null || true
    local waited=0
    while driver_up && (( waited < 10 )); do sleep 1; waited=$((waited + 1)); done
    kill -- "-$DRIVER_PID" 2>/dev/null || kill "$DRIVER_PID" 2>/dev/null || true
  fi
  # Anything left of its browser.
  pkill -f -- "graeae-real-media/$DRIVER_LABEL" 2>/dev/null || true
  pkill -f -- "--name $DRIVER_LABEL" 2>/dev/null || true
  exec 3>&-
  [[ -n "$DRIVER_DISPLAY" ]] && { scripts/real-media/desktop.sh stop "$DRIVER_DISPLAY" >/dev/null 2>&1 || true; }
  [[ -n "$DRIVER_DIR" ]] && rm -rf "$DRIVER_DIR"
  DRIVER_PID=""; DRIVER_DIR=""; DRIVER_DISPLAY=""; LINUX_SHARING=0
}
trap 'stop_driver' EXIT
trap 'exit 130' INT TERM

# The Linux member shares a white document that plays a beating 440 Hz tone, as a tab.
linux_share_page() {
  (( LINUX_SHARING )) && return 0
  send "content document $PAGE_TITLE \"\" \"\" \"\" 440" || return 1
  sleep 3
  send "share screen" || return 1
  sleep 6
  if grep -q "failed: share screen" "$DRIVER_DIR/log"; then
    warn "the Linux member's share did not start; see its readings below"
    return 1
  fi
  LINUX_SHARING=1
}

need_linux() {
  driver_up && return 0
  warn "The Linux member is not running (its start was skipped or failed), so this check waits for a later run."
  pause "Press Enter to go on…"
  return 1
}

# ── Which checks are left ─────────────────────────────────────────────────

ALL_IDS=(back-in step3-windows-share step5-linux-tab t32-click-for-sound t32-light-pill
  t32-webcam t32-game t32-fullscreen-strip brave-1080p60 launcher-audio zen-watch zen-webcam zen-screen)
LINUX_IDS=(step3-windows-share step5-linux-tab t32-click-for-sound t32-light-pill)
BRAVE_IDS=(t32-webcam t32-game t32-fullscreen-strip brave-1080p60 launcher-audio)
ZEN_IDS=(zen-watch zen-webcam zen-screen)

already=()
for id in "${ALL_IDS[@]}"; do if recorded "$id"; then already+=("$id"); fi; done
if (( ${#already[@]} )); then
  _clear
  printf '\n%sAlready recorded in %s:%s\n' "$BOLD" "${RESULTS#"$ROOT"/}" "$RESET"
  grep -F "· \`" "$RESULTS" | sed -n '/^- [0-9]/p' | sed 's/^/  /'
  printf '\n'
  read -e -r -p "  Redo any? Type their names (e.g. t32-game zen-webcam), or Enter for none: " -a REDO || true
fi

# Decided once, so a part's closing stage runs even after its checks are recorded.
LINUX_PART=0; BRAVE_PART=0; ZEN_PART=0
if any_pending "${LINUX_IDS[@]}"; then LINUX_PART=1; fi
if any_pending "${BRAVE_IDS[@]}"; then BRAVE_PART=1; fi
if any_pending "${ZEN_IDS[@]}"; then ZEN_PART=1; fi

# Before you start; each part's opening stage, and the Linux part's closing one; one stage
# per check left.
TOTAL_STAGES=$((1 + LINUX_PART * 2 + BRAVE_PART + ZEN_PART))
for id in back-in "${LINUX_IDS[@]}" "${BRAVE_IDS[@]}" "${ZEN_IDS[@]}"; do
  if pending "$id"; then TOTAL_STAGES=$((TOTAL_STAGES + 1)); fi
done

banner "graeae 0.1: the owner's checks on real machines"

# ── Before you start ──────────────────────────────────────────────────────

stage "Before you start"
say "On hand: the Windows 11 PC with Chrome, Brave and Zen, a real webcam, a game you can run"
say "windowed at 1080p, and a game started through a launcher (Steam, Epic, Battle.net…). Set"
say "the Windows monitor to 120 Hz: at 144 Hz Chrome captures at 48 fps (the README's 144 Hz"
say "caveat)."
printf '\n'
say "Everything happens on graeae-test, never the old prototype. Its address is"
say "https://graeae-test.<your workers.dev subdomain>.workers.dev; the subdomain is under"
say "Workers & Pages in the dashboard."
printf '\n'
ask GRAEAE_INSTANCE "graeae-test's address:"
GRAEAE_INSTANCE="${GRAEAE_INSTANCE%/}"
write_env GRAEAE_INSTANCE "$GRAEAE_INSTANCE"
sleep 1

# ── 1. Getting back in ────────────────────────────────────────────────────

if pending back-in; then
  stage "Getting back in as graeae-test's owner (README, Looking after an instance)"
  say "On Windows, in Chrome, open this address (copy it from here; it holds your setup secret,"
  say "so paste it nowhere else):"
  printf '\n'
  if [[ -r "$SECRET_FILE" ]]; then
    printf '    %s%s/setup#%s%s\n' "$BOLD" "$GRAEAE_INSTANCE" "$(tr -d '[:space:]' < "$SECRET_FILE")" "$RESET"
  else
    printf '    %s%s/setup#<your setup secret, from your password manager>%s\n' "$BOLD" "$GRAEAE_INSTANCE" "$RESET"
  fi
  printf '\n'
  step "Chrome becomes an owner device and lands in the first room; every other owner device is forgotten."
  step "Check the gear in the room's bar opens the owner page."
  note "Pass: you land in a room as the owner, with the gear. Chrome stays your owner browser for the rest."
  record back-in "Getting back in: /setup#<secret> on Windows Chrome makes it the owner"
fi

# ── 2. The Linux member, for steps 3 and 5 ────────────────────────────────

if (( LINUX_PART )); then
  stage "A Linux member joins the room"
  say "A Chromium on this machine joins as a member, to watch your Windows share (step 3) and to"
  say "share a tab with sound for you to watch (step 5)."
  printf '\n'
  step "In Windows Chrome, in the room you will use, open the gear (the owner page)."
  step "Under Invites: type the name $LINUX_NAME, tick only that room, press Create and copy link."
  printf '\n'
  ask OWNER_NAME "Your own display name in graeae, exactly as the room shows it:"
  write_env OWNER_NAME "$OWNER_NAME"
  invite=""
  until [[ "$invite" == https://*/invite/* ]]; do
    read -e -r -p "  Paste the invite link (https://…/invite/…): " invite || exit 1
  done
  [[ "$invite" == "$GRAEAE_INSTANCE"/* ]] || warn "that invite is not on $GRAEAE_INSTANCE; using it anyway"
  if ! start_driver "$invite"; then
    warn "The Linux checks stay unrecorded; run the wizard again to retry them."
    pause "Press Enter to go on…"
  else
    note "In Windows Chrome, $LINUX_NAME should now be in the room's bar."
    sleep 2
  fi
fi

if pending step3-windows-share && need_linux; then
  stage "Step 3: the Linux member watches your Windows screen share, picture and sound"
  step "On Windows, make something play sound: a game, or a video in another window."
  step "In Chrome: Share screen. In the picker either choose the Window that plays the sound, or"
  step "Entire screen with \"Also share system audio\" on. Press Share."
  step "Check Chrome's own preview shows it and no \"Video only\" line sits under it."
  pause "Press Enter once you are sharing…"
  send "watch \"$OWNER_NAME\" screen" || true
  sleep 8
  live
  say "Pass: 'in video' at your share's size near 60 fps with 'decoded' rising, and 'in audio'"
  say "level above 0.01 while sound plays (near 0 when it is quiet)."
  record step3-windows-share "Step 3: a Linux Chromium member watches a Windows Chrome screen share with audio" \
    "Linux member read: $(readings in)"
  send "unwatch \"$OWNER_NAME\" screen" || true
  note "Stop your share in Chrome now (its Stop under your preview)."
  pause "Press Enter once it has stopped…"
fi

if pending step5-linux-tab && need_linux; then
  stage "Step 5: the Linux member shares a tab playing sound; you watch and listen on Windows"
  say "The Linux member opens a white document in a tab, playing a 440 Hz tone that beats twice a"
  say "second, and shares that tab."
  if linux_share_page; then
    printf '\n'
    step "In Windows Chrome, in the room's bar, press the screen icon beside $LINUX_NAME to watch it."
    step "You should see the document, with a clock ticking in its bottom right corner, and hear"
    step "the tone (click the picture if it says \"Click for sound\"). The caption has no \"video only\"."
    live
    record step5-linux-tab "Step 5: a Linux Chromium member shares a tab with sound, watched and heard on Windows Chrome" \
      "Linux member sent: $(readings out)"
  else
    tail -n 10 "$DRIVER_DIR/log" | sed 's/^/    /'
    record step5-linux-tab "Step 5: a Linux Chromium member shares a tab with sound, watched and heard on Windows Chrome" \
      "the Linux member's tab share did not start"
  fi
fi

if pending t32-click-for-sound && need_linux; then
  stage "Ticket 32: the hover pill and \"Click for sound\" over bright content"
  linux_share_page || warn "the Linux member is not sharing; this check needs its white page"
  say "Windows Chrome, dark theme, watching $LINUX_NAME's white document."
  step "Hover the picture: is the pill (volume, Focus, Fullscreen, Stop watching) readable over white?"
  step "Press F5 to reload, and do not click anywhere on the page. Does \"Click for sound\" show over"
  step "the white picture, and is it readable? Click it: the tone comes in."
  step "If it never showed: copy the room's address, close the tab, paste it into a new tab, and"
  step "again do not click. Say in the note whether Chrome showed it at all."
  record t32-click-for-sound "Ticket 32: hover pill and \"Click for sound\" over a white document on a real Windows panel"
fi

if pending t32-light-pill && need_linux; then
  stage "Ticket 32: the light theme's pill edge over white"
  linux_share_page || warn "the Linux member is not sharing; this check needs its white page"
  step "In Windows Chrome: your avatar at the top of the bar, then Light."
  step "Hover $LINUX_NAME's white picture. On this real panel, can you tell where the pill ends"
  step "and the white page begins? Agents found the edge faint but the icons clear."
  step "Then switch back to the theme you use."
  record t32-light-pill "Ticket 32: the light theme's hover pill edge over white on a real panel"
fi

if (( LINUX_PART )); then
  stage "Stopping the Linux member"
  if driver_up; then
    (( LINUX_SHARING )) && { send "stop screen" || true; sleep 2; }
    send "closecontent" || true
    stop_driver
    printf '  %s✓ the Linux member, its display and its sound server are stopped%s\n' "$GREEN" "$RESET"
  else
    stop_driver
    note "It was not running."
  fi
  printf '\n'
  warn "Now remove it from graeae-test: in Windows Chrome open the gear, People, $LINUX_NAME,"
  warn "then Remove from graeae and confirm. (If the invite was never used, delete it under Invites.)"
  pause "Press Enter once $LINUX_NAME is removed…"
fi

# ── 3. Ticket 32 on Windows, with Brave as the viewer ─────────────────────

if (( BRAVE_PART )); then
  stage "Brave joins the room as a second member"
  say "The next checks need a second browser on Windows: Chrome shares, Brave watches, and"
  say "later the other way round. If Brave is already in from an earlier run, just open the"
  say "room there and go on."
  printf '\n'
  step "In Chrome, the gear, Invites: name it \"$OWNER_NAME (Brave)\", tick this room, Create and copy link."
  step "Open the link in Brave, press the button, and land in the same room. If Brave blocks"
  step "anything with its Shields, note it: the checks are at Brave's default settings."
  step "Arrange the two windows so you can see Brave's stage (a second monitor helps)."
  pause "Press Enter once Brave is in the room…"
fi

if pending t32-webcam; then
  stage "Ticket 32: a real webcam in a tile"
  step "In Chrome: Share webcam (your real one). Your own preview should be mirrored and read as a mirror."
  step "In Brave: watch your webcam. A 4:3 camera sits between bars in its 16:9 frame: does it look"
  step "intended, not broken? Look in dark and in light (avatar menu), maximised and in a smaller window."
  note "Leave the webcam on: the strip check uses it."
  record t32-webcam "Ticket 32: a real webcam in a tile, and the mirrored own preview, on Windows"
fi

if pending t32-game; then
  stage "Ticket 32: a real game in a tile"
  step "Start a game, windowed or borderless at 1920x1080, with the monitor at 120 Hz."
  step "In Chrome: Share screen, the Window tab, the game, Share. Chrome's preview shows all of"
  step "the game; there should be no \"Encoded in software…\" line under it."
  step "In Brave: watch your screen and play for a minute. Does the game look right in its tile:"
  step "smooth, sharp, colours true? Look in dark and light."
  note "The share now goes out as H.264 high at full size: a soft or blocky picture in fast motion is a fail."
  note "For the encoder and fps see the next checks; if you want them here, chrome://webrtc-internals in Chrome."
  record t32-game "Ticket 32: a real game in a tile, shared from Windows Chrome on the hardware encoder"
fi

if pending t32-fullscreen-strip; then
  stage "Ticket 32: fullscreen, and the strip"
  say "Chrome is sharing your webcam and the game; Brave watches both."
  step "In Brave, hover the game's tile and press Fullscreen: it fills the screen on the dark"
  step "letterbox, the pill shows in a corner while you move the mouse. Esc to leave."
  step "Hover the webcam's tile and press Focus: the game drops to the strip at 96px. Does the game"
  step "read as a picture, and does the caption keep your name whole (the kind gives way first)?"
  step "Look in dark and light. Then Back to the grid, and stop the webcam and the game's share in Chrome."
  record t32-fullscreen-strip "Ticket 32: a real game fullscreen and in the strip, on Windows"
fi

# ── 4. Remaining browser checks (v1 ticket 21), on graeae-test ────────────

webrtc_help() {
  local scheme="$1"
  say "Reading the encoder: before sharing, open a new tab in the sharing browser at"
  say "  ${BOLD}$scheme://webrtc-internals${RESET}"
  say "During the share: pick graeae-test's connection at the top, open \"Stats Tables\", and"
  say "find the ${BOLD}outbound-rtp${RESET} entry with kind=video. Read:"
  say "  encoderImplementation: hardware names an accelerator (D3D12VideoEncodeAccelerator on the"
  say "    Windows evidence run); OpenH264 or libvpx means software. powerEfficientEncoder=true is hardware."
  say "  The codec its codecId points to: profile-level-id=6400xx (H.264 high, any level) for a screen"
  say "    share from Chrome or Brave, 42001f for a webcam."
  say "  framesPerSecond near 60, and frameWidth x frameHeight 1920 x 1080."
  say "  Its graph of framesPerSecond shows whether the 2 minutes held 60."
  say "graeae says the same under the sharer's preview: \"Encoded in software…\" or \"Capturing at 48 fps…\"."
}

# browser_check ID Browser scheme
browser_check() {
  local id="$1" browser="$2" scheme="$3" encoder="" fps="" size="" heard=""
  webrtc_help "$scheme"
  printf '\n'
  step "Start the game, windowed or borderless at 1920x1080, monitor at 120 Hz, sound on."
  step "In $browser: Share screen, the Window tab, the game's window, with its audio on, Share."
  step "In Chrome: watch $browser's screen and listen."
  pause "Press Enter when the share is up and the game is moving, to start 2 minutes…"
  countdown 120 "2 minutes of play"
  ask_line encoder "encoderImplementation:"
  ask_line fps "framesPerSecond (roughly, and whether it held):"
  ask_line size "frameWidth x frameHeight:"
  ask_line heard "Did Chrome hear the game, and only the game?"
  note "Pass: hardware H.264 at about 60 fps and 1920x1080 for the 2 minutes, with the game's sound."
  record "$id" "v1/21: $browser on Windows 11 shares a game window at 1080p60 with hardware H.264 for 2 minutes" \
    "encoder $encoder; ${fps} fps; $size; sound: $heard"
  note "Stop the share in $browser."
  pause "Press Enter to go on…"
}

# ask_line VAR "Prompt" reads one visible line, not kept anywhere.
ask_line() {
  local input=""
  read -e -r -p "  $2 " input || true
  printf -v "$1" '%s' "${input:-?}"
}

if pending brave-1080p60; then
  stage "v1/21: Brave shares a game at 1080p60 with hardware H.264"
  browser_check brave-1080p60 Brave brave
fi

if pending launcher-audio; then
  stage "v1/21: a game started through a launcher; the viewer hears only the game"
  step "Start a game through its launcher (Steam, Epic, Battle.net…) and leave the launcher running."
  step "Make the launcher or another app sound too if you can (a friend's message, a store video,"
  step "music in another window), so a leak would be heard."
  step "In Chrome: Share screen, the Window tab, the game's window (not the launcher), audio on, Share."
  step "In Brave: watch it and listen for 30 seconds or so."
  note "Pass: Brave hears the game and nothing else. Fail: launcher or other sound comes through,"
  note "or no game sound at all. Name the game and the launcher in the note."
  record launcher-audio "v1/21: a launcher-started game's window shared from Windows Chrome; the viewer hears only the game"
  note "Stop the share in Chrome."
  pause "Press Enter to go on…"
fi

# ── 5. Zen at the Firefox level (v1 ticket 21) ────────────────────────────

if (( ZEN_PART )); then
  stage "Zen joins the room as a third member"
  say "Zen is built on Firefox, so it gets the Windows Firefox row's promise: it watches"
  say "everything with screen audio and shares a webcam fully; its screen share is video only,"
  say "with no quality promise. If Zen is already in from an earlier run, just open the room there."
  printf '\n'
  step "Update Zen (its menu, Help, About Zen) and note its version."
  ask ZEN_VERSION "Zen version:"
  write_env ZEN_VERSION "$ZEN_VERSION"
  step "In Chrome, the gear, Invites: name it \"$OWNER_NAME (Zen)\", tick this room, Create and copy link."
  step "Open the link in Zen, press the button, and land in the same room."
  pause "Press Enter once Zen is in the room…"
fi
ZEN="Zen ${ZEN_VERSION:-?} on Windows 11"

if pending zen-watch; then
  stage "v1/21: Zen watches a Chrome screen share with its audio"
  step "On Windows, make something play sound: a game, or a video in another window."
  step "In Chrome: Share screen, the Window tab, that window, with its audio on, Share."
  step "In Zen: watch it for a minute and listen (click the picture if it says \"Click for sound\")."
  note "Pass: Zen shows it moving smoothly and plays its sound, and the caption has no \"video only\"."
  record zen-watch "v1/21: Zen on Windows 11 watches a Windows Chrome screen share, picture and screen audio" "$ZEN"
  note "Stop the share in Chrome."
  pause "Press Enter to go on…"
fi

if pending zen-webcam; then
  stage "v1/21: Zen shares a webcam"
  step "In Zen: Share webcam, and allow the camera when Zen asks. Your own preview is mirrored."
  step "In Chrome: watch it. For its size and rate, open chrome://webrtc-internals in a new tab,"
  step "pick graeae-test's connection, Stats Tables, the inbound-rtp entry with kind=video."
  ask_line size "frameWidth x frameHeight in Chrome (1280 x 720 is the aim):"
  ask_line fps "framesPerSecond in Chrome (30 is the aim):"
  note "Pass: Chrome sees the webcam moving, at about 1280x720 and 30 fps (less only if the camera"
  note "itself gives less)."
  record zen-webcam "v1/21: Zen on Windows 11 shares a webcam, watched in Windows Chrome" "$ZEN; Chrome read $size at $fps fps"
  note "Stop the webcam in Zen."
  pause "Press Enter to go on…"
fi

if pending zen-screen; then
  stage "v1/21: Zen shares a screen as video only"
  step "In Zen: Share screen. The first time, a notice comes before the picker; it says \"In Firefox,"
  step "a screen share is video only…\". Say in the note whether that reads right in Zen."
  step "In Zen's picker, choose a window that plays sound (or the whole screen), and Allow."
  step "Under Zen's own preview: \"Video only. No one hears this share.\""
  step "In Chrome: watch it for a minute."
  note "Pass: Chrome sees it moving, its caption says \"screen · video only\", and nothing is heard."
  note "Smoothness and sharpness are not promised, but say how it looked."
  record zen-screen "v1/21: Zen on Windows 11 shares a screen, seen in Windows Chrome as video only" "$ZEN"
  note "Stop the share in Zen."
  pause "Press Enter to go on…"
fi

finish
if (( ${#DONE_THIS_RUN[@]} )); then
  say "Recorded this run in ${RESULTS#"$ROOT"/}:"
  for line in "${DONE_THIS_RUN[@]}"; do note "  $line"; done
else
  say "Nothing recorded this run."
fi
left=()
for id in "${ALL_IDS[@]}"; do
  if recorded "$id"; then continue; fi
  left+=("$id")
done
if (( ${#left[@]} )); then
  printf '\n'; warn "Still unrecorded: ${left[*]}"
  note "Run scripts/owner-checks.sh again for them."
fi
say "Hand the results to an agent to apply: the platform table, ticket 21 and ticket 25."
printf '\n'
}

run_wizard "$@"; exit
